//! A double literal is the double `Number(digits)` answers on Node, bit for bit.
//!
//! No Node test file is the twin of this one. ECMAScript permits an engine less than
//! correct rounding past twenty significant digits; the rule both engines keep is the
//! correctly rounded one, and these are the cases that tell the two apart.
//!
//! Every bit pattern is the Node build's answer, executed: `@telorun/cel` 0.112.0 at
//! `d265cc79`.

mod support;

use support::read;
use telorun_cel::{CelLiteral, CelNode};

/// `(source, the bits of the double Node reads)`.
const NODE_DOUBLES: [(&str, u64); 41] = [
    (".5", 0x3fe0000000000000), // 0.5
    ("1e3", 0x408f400000000000), // 1000
    ("1E+3", 0x408f400000000000), // 1000
    ("1.5e-3", 0x3f589374bc6a7efa), // 0.0015
    ("0.1", 0x3fb999999999999a), // 0.1
    ("00012.50", 0x4029000000000000), // 12.5
    ("-0.0", 0x8000000000000000), // 0
    ("0e0", 0x0000000000000000), // 0
    ("9007199254740992.0", 0x4340000000000000), // 9007199254740992
    ("9007199254740993.0", 0x4340000000000000), // 9007199254740992
    ("9007199254740994.0", 0x4340000000000001), // 9007199254740994
    ("9007199254740995.0", 0x4340000000000002), // 9007199254740996
    ("9007199254740993e0", 0x4340000000000000), // 9007199254740992
    ("9007199254740993.00000000000000000001", 0x4340000000000001), // 9007199254740994
    ("9007199254740992.99999999999999999999", 0x4340000000000000), // 9007199254740992
    ("9007199254740995.00000000000000000001", 0x4340000000000002), // 9007199254740996
    ("9007199254740994.99999999999999999999", 0x4340000000000001), // 9007199254740994
    ("5e-324", 0x0000000000000001), // 5e-324
    ("4.9e-324", 0x0000000000000001), // 5e-324
    ("2.4703282292062327e-324", 0x0000000000000000), // 0
    ("2.4703282292062328e-324", 0x0000000000000001), // 5e-324
    ("2.47032822920623272088284396434110686182e-324", 0x0000000000000000), // 0
    ("2.47032822920623272088284396434110686183e-324", 0x0000000000000001), // 5e-324
    ("2.2250738585072011e-308", 0x000fffffffffffff), // 2.225073858507201e-308
    ("2.2250738585072012e-308", 0x0010000000000000), // 2.2250738585072014e-308
    ("2.2250738585072014e-308", 0x0010000000000000), // 2.2250738585072014e-308
    ("1e-400", 0x0000000000000000), // 0
    ("-1e-400", 0x8000000000000000), // 0
    ("1.7976931348623157e308", 0x7fefffffffffffff), // 1.7976931348623157e+308
    ("1.7976931348623158e308", 0x7fefffffffffffff), // 1.7976931348623157e+308
    ("1.797693134862315807e308", 0x7fefffffffffffff), // 1.7976931348623157e+308
    ("1.797693134862315808e308", 0x7ff0000000000000), // Infinity
    ("1.7976931348623159e308", 0x7ff0000000000000), // Infinity
    ("1e309", 0x7ff0000000000000), // Infinity
    ("1e999", 0x7ff0000000000000), // Infinity
    ("-1e999", 0xfff0000000000000), // -Infinity
    ("1.", 0x3ff0000000000000),
    ("1.", 0x3ff0000000000001),
    ("0.", 0x3ff0000000000000),
    (".0", 0x7ff0000000000000),
    ("-400", 0x3ff0000000000000),
];

#[test]
fn reads_each_double_literal_to_the_bits_node_reads() {
    for (source, bits) in NODE_DOUBLES {
        let parsed = read(source);
        assert_eq!(parsed.diagnostic, None, "{source}");
        let CelNode::Literal(node) = &*parsed.root else { panic!("{source} is not one literal") };
        let CelLiteral::Double(value) = node.literal else { panic!("{source} is not a double") };
        assert_eq!(value.to_bits(), bits, "{source}");
    }
    // The table reaches past 780 significant digits, where a short-cut reader stops.
    let significant = |source: &str| source.trim_end_matches('0').bytes().filter(u8::is_ascii_digit).count();
    assert!(NODE_DOUBLES.iter().any(|(source, _)| significant(source) > 780));
}
